// ── Small components ────────────────────────────────────────────
const Tag = ({ label }) => (
  <span className="inline-flex items-center rounded-full border border-black/10 px-3 py-0.5 font-['DM_Sans'] text-[11px] text-black/60">
    {label}
  </span>
);

const Meta = ({ date, read, light = false }) => (
  <span className={`font-['DM_Sans'] text-[11px] ${light ? "text-white/50" : "text-black/40"}`}>
    {date} &nbsp;·&nbsp; {read}
  </span>
);

const ArrowLink = ({ href = "#", to = null, light = false }) => {
  const cls = `mt-4 inline-flex items-center gap-1 font-['DM_Sans'] text-[12px] font-medium transition-opacity hover:opacity-70 ${light ? "text-white" : "text-black"}`;
  const content = (
    <>
      Read Full Article
      <svg width="14" height="14" viewBox="0 0 14 14" fill="none">
        <path d="M2 7h10M7 2l5 5-5 5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    </>
  );
  if (to) return <Link to={to} className={cls}>{content}</Link>;
  return <a href={href} className={cls}>{content}</a>;
};

